<script setup lang="ts">
import {computed,onMounted,onUnmounted,reactive,ref,watch,nextTick} from 'vue';
import Fields from './Fields.vue';
import AccountPanel from './AccountPanel.vue';
import PaymentOptions from './PaymentOptions.vue';
import OrderPayment from './OrderPayment.vue';
import AdminReview from './AdminReview.vue';
import AdminTeam from './AdminTeam.vue';
import TelegramPanel from './TelegramPanel.vue';
import SubscriptionsPanel from './SubscriptionsPanel.vue';
import ClientHelp from './ClientHelp.vue';
import {fields,defaults,localDate} from './schema';
import {traffic,money,date,states,buyKey} from './lib';
type Row=Record<string,any>;
const user=ref<Row|null>(null),csrf=ref(''),page=ref('overview'),busy=ref(false),error=ref(''),notice=ref('');
const branding=ref<Row>({title:'星枢用户中心',traffic_unit:'GB',announcements:[]}),catalog=ref<Row>({plans:[],categories:[]}),orders=ref<Row[]>([]),service=ref<Row|null>(null),devices=ref<Row[]>([]),tickets=ref<Row[]>([]),rows=ref<Row[]>([]),groups=ref<Row[]>([]),categories=ref<Row[]>([]),version=ref<Row>({}),capacity=ref<Row>({}),config=ref<Row|null>(null);
const authMode=ref('login'),auth=reactive({email:'',password:'',name:'',invitation:'',token:'',password_confirm:''});
const admin=computed(()=>user.value?.role==='admin');
const can=(scope:string)=>!!user.value?.is_owner||!!user.value?.admin_scopes?.includes(scope);
const tabs=computed(()=>admin.value?[
 ['overview','概览','◈',''],['plans','套餐管理','▦','plans'],['catalog','套餐展示预览','▦','plans'],['categories','套餐分类','▤','plans'],['customers','用户与审核','♙','customers'],['orders','订单与开通','▣','orders'],['manual-payments','人工核款','✓','payments'],['coupons','优惠码','◇','coupons'],['invitations','注册邀请','✉','invitations'],['announcements','公告','◎','announcements'],['tickets','服务工单','☏','support'],['payment-methods','收款方式','▧','owner'],['administrators','管理员','♙','owner'],['telegram','Telegram 机器人','✉','owner'],['settings','站点与连接','⚙','owner'],['version','版本与更新','↻','owner'],['jobs','后台任务','⋯','jobs'],['audit','操作记录','≡','audit'],['help','客户端教程','?',''],['account','个人账户','○','']
].filter(t=>!t[3]||(t[3]==='owner'?user.value?.is_owner:can(t[3]))):[['overview','我的服务','◈'],['catalog','选购套餐','▦'],['orders','我的订单','▣'],['subscription','订阅与设备','↗'],['tickets','服务工单','☏'],['help','客户端教程','?'],['account','个人账户','○']]);
const title=computed(()=>tabs.value.find(x=>x[0]===page.value)?.[1]||'用户中心');
const editor=ref(''),form=ref<Row>({}),selectedPlan=ref<Row|null>(null),buy=reactive({plan_id:'',price_id:'',coupon:'',request_key:''}),quote=ref<Row|null>(null),thread=ref<Row|null>(null),ticketForm=reactive({subject:'',body:''});
const payOrder=ref<Row|null>(null),serviceTarget=ref('');
const settingsForm=ref<Row>({}),secretForm=ref<Row>({}),paymentForm=ref<Row>({}),allowlist=ref('');
const planFields=computed(()=>fields[editor.value]?.map(f=>f.key==='category_id'?{...f,options:categories.value.map(c=>({value:c.id,label:c.name}))}:f)||[]);
const protocols=computed(()=>[...new Set(groups.value.filter(g=>form.value.group_ids?.includes(g.id)).flatMap(g=>g.services.filter((s:Row)=>s.managed_users).map((s:Row)=>s.protocol)))].sort() as string[]);
const stats=computed(()=>({customers:rows.value.filter(x=>x.role==='customer').length,paid:orders.value.filter(x=>x.state==='paid').reduce((n,x)=>n+Number(x.payable),0),pending:orders.value.filter(x=>x.state==='pending').length}));
async function request(path:string,method='GET',body?:unknown){const res=await fetch('/portal/v1/'+path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json',...(csrf.value?{'X-CSRF-Token':csrf.value}:{})},body:body===undefined?undefined:JSON.stringify(body)});const data=await res.json().catch(()=>({error:'服务响应格式错误'}));if(!res.ok)throw new Error(data.error||`请求失败 ${res.status}`);return data;}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
async function load(){if(!user.value)return;if(['account','payment-methods','manual-payments','administrators','telegram','help'].includes(page.value)||!admin.value&&page.value==='subscription')return;if(page.value==='catalog'){catalog.value=await request('catalog');return;}if(admin.value){
 if(page.value==='settings'){const cfg=await request('admin/settings');config.value=cfg;settingsForm.value={...cfg.settings};allowlist.value=(settingsForm.value.email_allowlist||[]).join('\n');const s=cfg.secrets;secretForm.value={control_origin:s.control_origin||'',control_key:'',smtp_host:s.smtp_host||'',smtp_port:s.smtp_port||587,smtp_user:s.smtp_user||'',smtp_password:'',smtp_from:s.smtp_from||''};paymentForm.value={enabled:false,sandbox:false,app_id:'',seller_id:'',mobile:true,...s.alipay,private_key:'',public_key:''};return}
 if(page.value==='version'){[version.value,capacity.value]=await Promise.all([request('admin/version'),request('admin/capacity').catch(e=>({error:String(e)}))]);return}
 if(page.value==='overview'){[rows.value,orders.value]=await Promise.all([can('customers')?request('admin/customers'):Promise.resolve([]),can('orders')?request('admin/orders'):Promise.resolve([])]);return}
 rows.value=await request('admin/'+page.value);if(page.value==='plans'){categories.value=await request('admin/categories');try{const g=await request('admin/control-groups');groups.value=g.groups||[]}catch(e){groups.value=[];error.value=String(e)}}
 }else{if(page.value==='overview'){const data=await request('me/service');service.value=data.service;orders.value=await request('orders')}
 if(page.value==='catalog')catalog.value=await request('catalog');if(page.value==='orders')orders.value=await request('orders');

 if(page.value==='tickets')tickets.value=await request('tickets');}}
async function initialize(){try{branding.value=await request('public');document.title=branding.value.title;const me=await request('me');user.value=me.user;csrf.value=me.csrf;await load()}catch(e){if(user.value)error.value=String(e)}
 const fragment=new URLSearchParams(location.hash.slice(1));if(fragment.has('verify')){auth.token=fragment.get('verify')||'';authMode.value='verify'}if(fragment.has('reset')){auth.token=fragment.get('reset')||'';authMode.value='reset'}if(fragment.has('verify-email')){auth.token=fragment.get('verify-email')||'';authMode.value='verify-email'}if(auth.token){user.value=null;history.replaceState(null,'',location.pathname);}}
async function authenticate(){await run(async()=>{if(['register','reset'].includes(authMode.value)&&auth.password!==auth.password_confirm)throw new Error('两次输入的密码不一致');if(authMode.value==='login'){const data=await request('auth/login','POST',{email:auth.email,password:auth.password});csrf.value=data.csrf;user.value=data.user;auth.password='';await load();return}
 const payload=authMode.value==='register'?{email:auth.email,name:auth.name,password:auth.password,invitation:auth.invitation,password_confirm:auth.password_confirm}:authMode.value==='forgot'?{email:auth.email}:['verify','verify-email'].includes(authMode.value)?{token:auth.token}:{token:auth.token,password:auth.password,password_confirm:auth.password_confirm};const d=await request('auth/'+authMode.value,'POST',payload);notice.value=d.message||(d.status==='pending'?'邮箱已验证，请等待管理员审核':'操作成功，请登录');authMode.value='login';auth.password='';auth.password_confirm='';auth.token='';});}
async function logout(){await run(async()=>{await request('auth/logout','POST',{});user.value=null;csrf.value='';page.value='overview'})}
function openEditor(kind:string,row?:Row){editor.value=kind;error.value='';form.value=defaults(kind);if(kind==='invitations')form.value.max_uses=1;
 if(row){for(const f of fields[kind]||[]){if(f.key==='quota_gb'){form.value.quota_gb=Number(row.quota_bytes)/(row.quota_unit==='GiB'?1073741824:1e9);continue}let v=row[f.key];if(v!==undefined)form.value[f.key]=f.type==='json'?JSON.stringify(v,null,2):f.type==='datetime-local'?localDate(new Date(v)):v;}for(const k of ['id','version','group_ids','protocols','prices','display_features'])if(row[k]!==undefined)form.value[k]=JSON.parse(JSON.stringify(row[k]));}
 else if(kind==='plans')form.value.category_id=categories.value[0]?.id||'';}
async function saveEditor(){await run(async()=>{const payload:Row={};for(const f of fields[editor.value]){if(f.key==='quota_gb')continue;let v=form.value[f.key];if(f.type==='json')v=JSON.parse(v||'[]');if(f.type==='datetime-local')v=new Date(v).toISOString();payload[f.key]=v;}for(const k of ['id','version'])if(form.value[k]!==undefined)payload[k]=form.value[k];if(editor.value==='plans'){payload.quota_bytes=Math.round(Number(form.value.quota_gb)*(form.value.quota_unit==='GiB'?1073741824:1e9));for(const k of ['group_ids','protocols','prices','display_features'])payload[k]=form.value[k];}
 const result=await request('admin/'+editor.value,form.value.id?'PUT':'POST',payload);editor.value='';notice.value=result.notice||'已保存';await load();});}
async function customerStatus(row:Row){await run(async()=>{const d=await request('admin/customers','PUT',{id:row.id,status:row.status==='active'?'disabled':'active'});notice.value=d.notice;await load()})}
function choose(plan:Row){if(!user.value){notice.value='请先登录再购买';return}selectedPlan.value=plan;Object.assign(buy,{plan_id:plan.id,price_id:plan.prices[0]?.id||'',coupon:'',request_key:buyKey()});quote.value=null;}
watch(()=>[buy.price_id,buy.coupon],()=>{quote.value=null;buy.request_key=buyKey()});
async function priceQuote(){await run(async()=>{quote.value=await request('checkout/quote','POST',buy)})}
async function placeOrder(){await run(async()=>{if(!quote.value)return;const d=await request('orders','POST',buy);selectedPlan.value=null;page.value='orders';await load();notice.value='订单已创建，请核对实付金额后支付。订单号：'+d.id})}
function payment(row:Row){payOrder.value=row}
async function cancelOrder(row:Row){await run(async()=>{const d=await request(`orders/${row.id}/cancel`,'POST',{});notice.value=d.message;await load()})}
async function copy(text:string){try{await navigator.clipboard.writeText(text);notice.value='已复制'}catch{notice.value='当前 IP 入口未提供剪贴板权限，请选中链接手动复制'}}
async function showTicket(row:Row){await run(async()=>{const d=await request('tickets/'+row.id);thread.value={...row,...d};ticketForm.body=''})}
async function sendTicket(close=false){await run(async()=>{if(thread.value)await request('tickets/'+thread.value.id,'POST',{body:ticketForm.body,close});else await request('tickets','POST',ticketForm);thread.value=null;editor.value='';ticketForm.subject='';ticketForm.body='';notice.value='工单已保存';await load()})}
async function saveSettings(){await run(async()=>{const s={...settingsForm.value,email_allowlist:allowlist.value.split(/[\n,]/).map(x=>x.trim()).filter(Boolean)};const {private_configured,public_configured,...p}=paymentForm.value;const d=await request('admin/settings','PUT',{settings:s,secrets:{...secretForm.value,alipay:p}});notice.value=d.notice;await load()})}
async function signedOut(message:string){user.value=null;csrf.value='';page.value='overview';await nextTick();notice.value=message}
async function seedDemos(){await run(async()=>{const d=await request('admin/demo-plans','POST',{});notice.value=d.message;await load()})}
async function update(){await run(async()=>{await request('admin/version','POST',{version:version.value.latest,current:version.value.current});notice.value='更新已进入任务队列。请等待健康检查完成；失败将尝试回滚。';await load()})}
let interval:ReturnType<typeof setInterval>;
onMounted(()=>{void initialize();interval=setInterval(()=>{if(document.visibilityState==='visible'&&user.value&&!busy.value&&!editor.value&&!selectedPlan.value&&!thread.value&&page.value!=='settings')void load().catch(()=>{});},30000)});
onUnmounted(()=>{clearInterval(interval)});
watch(page,()=>{rows.value=[];error.value='';notice.value='';void run(load)});
</script>

<template>
<div v-if="!user" class="auth-layout"><section class="intro"><a class="brand" href="/">✦ <span>STARHUB <small>星枢 · 用户中心</small></span></a><div><span class="eyebrow">STAY CONNECTED</span><h1>连接世界，<br>从这里开始。</h1><p>选择适合自己的套餐，<br>流量、订阅与服务，一处掌握。</p><div class="intro-tags"><span>独立身份</span><span>清晰用量</span><span>多端订阅</span></div></div><small>星枢用户中心 · {{branding.version||'加载中'}}</small></section>
<main class="auth-main"><div class="auth-box"><span class="eyebrow">WELCOME TO STARHUB</span><h2>{{({login:'欢迎回来',register:'创建账户',forgot:'找回密码',reset:'设置新密码',verify:'验证邮箱','verify-email':'验证新邮箱'} as Row)[authMode]}}</h2><p class="muted">{{authMode==='register'?(branding.registration_mode==='email'?'验证邮箱后完成注册。':'注册需要有效邀请或白名单，并验证邮箱。'):'管理你的订阅与连接服务'}}</p><div v-if="error" class="alert error" role="alert">{{error}}</div><div v-if="notice" class="alert" role="status">{{notice}}</div>
<form @submit.prevent="authenticate"><label v-if="!['verify','verify-email','reset'].includes(authMode)">邮箱<input v-model="auth.email" type="email" required autocomplete="username"></label><label v-if="authMode==='register'">昵称<input v-model="auth.name" required maxlength="80"></label><label v-if="['login','register','reset'].includes(authMode)">密码<input v-model="auth.password" type="password" required :minlength="authMode==='login'?1:12" maxlength="256" :autocomplete="authMode==='login'?'current-password':'new-password'"></label><label v-if="['register','reset'].includes(authMode)">再次输入密码<input v-model="auth.password_confirm" type="password" required minlength="12" maxlength="256" autocomplete="new-password"></label><p v-if="['register','reset'].includes(authMode)&&auth.password_confirm&&auth.password!==auth.password_confirm" class="alert error">两次输入的密码不一致</p><label v-if="authMode==='register'&&branding.registration_mode==='invite'">邀请码<input v-model="auth.invitation" required></label><button class="primary full" :disabled="busy||authMode==='register'&&!branding.email_ready||['register','reset'].includes(authMode)&&auth.password!==auth.password_confirm">{{busy?'处理中…':authMode==='login'?'登录':authMode==='verify'?'确认验证邮箱':'提交'}}</button></form><div class="auth-links"><button v-if="authMode!=='login'" @click="authMode='login'">返回登录</button><template v-else><button @click="authMode='forgot'">忘记密码</button><button v-if="branding.registration_mode!=='closed'" @click="authMode='register'">{{branding.registration_mode==='invite'?'使用邀请注册 →':'注册账户 →'}}</button></template></div><small v-if="!branding.email_ready&&authMode==='register'" class="muted">邮箱服务尚未就绪，请联系管理员。</small></div></main></div>

<div v-else class="shell"><aside class="sidebar"><a class="brand" href="/">✦ <span>STARHUB <small>{{admin?'运营管理台':'我的用户中心'}}</small></span></a><div class="nav-caption">{{admin?'WORKSPACE · 运营工作区':'MY ACCOUNT · 我的账户'}}</div><nav><button v-for="t in tabs" :key="t[0]" :disabled="busy" @click="page=t[0]" :class="{selected:page===t[0]}"><span>{{t[2]}}</span>{{t[1]}}</button></nav><div class="account"><div class="avatar">{{user.name.slice(0,1)}}</div><div><strong>{{user.name}}</strong><small>{{admin?(user.is_owner?'主管理员':'副管理员'):'购买用户'}}</small></div><button @click="logout" title="退出登录">↗</button></div></aside><main class="content"><header><div><div class="eyebrow">STARHUB / {{admin?'ADMINISTRATION':'PERSONAL'}}</div><h1>{{title}}</h1></div><button :disabled="busy" @click="run(load)">↻ 刷新</button></header><div v-if="error" class="alert error" role="alert">{{error}}</div><div v-if="notice" class="alert" role="status">{{notice}}</div>

<template v-if="page==='overview'"><section class="welcome"><div><span class="eyebrow">{{admin?'SERVICE CONSOLE':'YOUR CONNECTION, SIMPLIFIED'}}</span><h2>{{admin?'让每一份服务，清楚可控。':'你好，'+user.name+'。'}}</h2><p>{{admin?'套餐、用户与订单，组成你的运营工作区。':'在这里查看服务状态，管理套餐和多端订阅。'}}</p><button class="primary" @click="page=admin?(can('plans')?'plans':'account'):'catalog'">{{admin?(can('plans')?'管理套餐':'个人账户'):'查看套餐'}} →</button></div><div class="orb">✦</div></section><div class="metrics" v-if="admin&&user.is_owner"><article><span>购买用户</span><strong>{{stats.customers}}<small> 人</small></strong></article><article><span>最近订单中的已付金额</span><strong>{{money(stats.paid)}}</strong><small>最近 300 条订单，含待开通</small></article><article><span>待处理订单</span><strong>{{stats.pending}}<small> 笔</small></strong></article></div><div class="metrics" v-else-if="!admin"><article><span>最近订单剩余流量</span><strong>{{service?traffic(service.remaining_bytes,service.quota_unit||'GB'):'未开通'}}</strong></article><article><span>该订单已用 / 配额</span><strong>{{traffic(service?.used_bytes,service?.quota_unit||'GB')}}</strong><small>{{traffic(service?.quota_bytes,service?.quota_unit||'GB')}} / 月</small></article><article><span>该订单服务到期</span><strong class="date">{{date(service?.expires_at)}}</strong><small>下次流量重置：{{date(service?.next_reset_at)}}</small></article></div><section class="panel" v-if="!admin&&service"><div class="section-head"><h3>{{service.plan_name}}</h3><span class="badge">{{service.enabled?'服务已开通':'服务已停用'}}</span></div><progress :value="Number(service.used_bytes)||0" :max="Number(service.quota_bytes)||1"/><p class="muted">流量由星枢独立身份计量。显示值随主机回传更新。</p><button @click="page='subscription'">查看全部独立订阅 →</button></section><section class="panel"><h3>服务公告</h3><article v-for="a in branding.announcements" :key="a.id" class="announcement"><div class="announcement-title"><span v-if="a.pinned" class="badge pin-badge">置顶</span><strong>{{a.title}}</strong></div><p class="pre">{{a.body}}</p><small>{{date(a.created_at)}}</small></article><p v-if="!branding.announcements?.length" class="muted">暂无公告</p></section></template>

<template v-if="page==='catalog'"><p class="muted">仅分发可独立计量的授权协议；选购前会再次检查节点就绪状态。</p><section v-for="c in catalog.categories" :key="c.id"><div class="section-head"><h2>{{c.name}}</h2><p class="muted">{{c.description}}</p></div><div class="plan-grid"><article v-for="p in catalog.plans.filter((x:Row)=>x.category_id===c.id)" :key="p.id" class="plan" :class="{featured:p.recommended}"><span v-if="p.recommended" class="ribbon">{{p.simulation?'示例推荐':'推荐套餐'}}</span><span class="eyebrow">STARHUB PLAN</span><h2>{{p.name}} <span v-if="p.simulation" class="badge">模拟</span></h2><p class="pre muted">{{p.description}}</p><div class="price">{{money(p.prices[0]?.amount)}}<small> / {{p.prices[0]?.months}} 个月</small></div><ul><li>{{traffic(p.quota_bytes,p.quota_unit||'GB')}} 每月流量</li><li>{{p.protocols.join(' / ').toUpperCase()}}</li><li>{{p.max_devices?p.max_devices+' 台设备':'设备数不限'}}</li></ul><dl v-if="p.display_features?.length" class="plan-features"><div v-for="(f,i) in p.display_features" :key="i"><dt>{{f.label}}</dt><dd>{{f.value}}</dd></div></dl><button class="primary full" @click="choose(p)" :disabled="admin||!p.prices.length||p.simulation">{{p.simulation?'模拟套餐 · 暂不可购买':admin?'管理员预览':'选择套餐 →'}}</button></article></div></section><div v-if="!catalog.plans.length" class="empty">暂无可购买套餐，请关注公告。</div></template>

<template v-if="page==='orders'"><div class="panel table-wrap"><table><thead><tr><th>订单 / 套餐</th><th v-if="admin">购买用户</th><th>实付</th><th>支付状态</th><th>服务开通</th><th>创建 / 付款期限</th><th>操作</th></tr></thead><tbody><tr v-for="o in admin?rows:orders" :key="o.id"><td><strong>{{o.plan_name||o.snapshot?.plan?.name}}</strong><small class="mono">{{o.id}}</small></td><td v-if="admin">{{o.email}}</td><td>{{money(o.payable)}}<small>优惠 {{money(o.discount_amount)}}</small></td><td><span class="badge" :class="o.state">{{o.manual_state==='submitted'?'待人工核款':states[o.state]}}</span></td><td>{{states[o.fulfillment]}}</td><td>{{date(o.created_at)}}<small>期限 {{date(o.expires_at)}}</small></td><td><button v-if="!admin&&o.has_subscription" @click="serviceTarget=o.id;page='subscription'">查看此订单订阅</button><div class="actions" v-if="!admin&&(o.state==='pending'||o.manual_state)"><button class="primary" :disabled="busy||!o.manual_state&&new Date(o.expires_at).getTime()<Date.now()" @click="payment(o)">{{o.manual_state?'查看付款 / 凭证':'选择方式付款'}}</button><button v-if="o.state==='pending'&&o.manual_state!=='submitted'" @click="cancelOrder(o)">取消</button></div><span v-else class="muted">{{o.state==='late_paid'?'请联系管理员处理退款':'—'}}</span></td></tr></tbody></table><div v-if="!(admin?rows:orders).length" class="empty">暂无订单</div></div><p class="muted" v-if="!admin">付款窗口显示管理员已启用的支付宝 / 微信个人收款码或在线支付通道。</p></template>

<SubscriptionsPanel v-if="!admin&&page==='subscription'" :request="request" :initial="serviceTarget"/><ClientHelp v-if="page==='help'"/>

<template v-if="page==='tickets'"><section class="panel"><div class="section-head"><h3>{{admin?'用户工单':'我的工单'}}</h3><button v-if="!admin" @click="thread=null;editor='ticket'">＋ 创建工单</button></div><div v-for="t in admin?rows:tickets" :key="t.id" class="list-row"><div><strong>{{t.subject}}</strong><small>{{t.email||date(t.created_at)}}</small></div><span class="badge">{{states[t.state]}}</span><button @click="showTicket(t)">查看 / 回复</button></div><p class="empty" v-if="!(admin?rows:tickets).length">暂无工单</p></section></template>

<template v-if="admin&&page==='customers'"><div class="panel table-wrap"><table><thead><tr><th>用户</th><th>状态</th><th>注册时间</th><th>操作</th></tr></thead><tbody><tr v-for="c in rows" :key="c.id"><td><strong>{{c.name}}</strong><small>{{c.email}}</small><small class="mono">{{c.id}}</small></td><td>{{c.role==='admin'?'管理员':states[c.status]}}</td><td>{{date(c.created_at)}}</td><td><button v-if="c.role!=='admin'&&c.email_verified_at" @click="customerStatus(c)" :disabled="busy">{{c.status==='active'?'停用账户与代理权限':'批准 / 启用'}}</button></td></tr></tbody></table></div></template>

<AccountPanel v-if="page==='account'" :request="request" :user="user" @update="user=$event" @signed-out="signedOut"/><PaymentOptions v-if="admin&&page==='payment-methods'" :request="request"/><TelegramPanel v-if="admin&&page==='telegram'" :request="request"/><AdminReview v-if="admin&&page==='manual-payments'" :request="request"/><AdminTeam v-if="admin&&page==='administrators'" :request="request"/>
<template v-if="admin&&fields[page]"><div class="section-head"><p class="muted">{{page==='plans'?'绑定现有星枢用户组，并选择套餐允许的独立计费协议。':'保存历史记录；不再使用的条目可编辑停用。'}}</p><div class="actions"><button v-if="page==='plans'&&user.is_owner" @click="seedDemos" :disabled="busy">生成示例套餐</button><button class="primary" @click="openEditor(page)">＋ 新建{{title.replace('管理','')}}</button></div></div><div class="panel"><div v-for="r in rows" :key="r.id" class="list-row"><div><strong>{{r.name||r.title||r.prefix}} <span v-if="r.simulation" class="badge">模拟</span><span v-if="r.pinned" class="badge pin-badge">置顶 · {{r.pin_order}}</span></strong><small v-if="r.description">{{r.description}}</small><small class="mono">{{r.id}}</small><small v-if="page==='plans'">{{traffic(r.quota_bytes,r.quota_unit||'GB')}} / 月 · {{r.protocols?.join(' / ')}}</small><div v-if="page==='coupons'" class="code-line"><code>{{r.code}}</code><button @click="copy(r.code)">复制优惠码</button></div><small v-if="page==='coupons'">{{r.code}} · {{date(r.starts_at)}} — {{date(r.ends_at)}}</small><div v-if="page==='invitations'" class="code-line"><code v-if="r.code">{{r.code}}</code><small v-else>旧邀请码未保存原文，可编辑生成新码。</small><button v-if="r.code" @click="copy(r.code)">复制邀请码</button></div><small v-if="page==='invitations'">已占用 {{r.claimed}} / {{r.max_uses}} · {{r.email||'不限邮箱'}}</small></div><span class="badge">{{r.enabled?'已启用':'已停用'}}</span><button @click="openEditor(page,r)">编辑</button></div><div v-if="!rows.length" class="empty">暂无内容，点击右上角创建。</div></div></template>

<template v-if="admin&&page==='settings'&&config"><form @submit.prevent="saveSettings"><section class="panel"><h3>品牌与访问入口</h3><div class="fields"><label>站点名称<input v-model="settingsForm.title" required maxlength="40"></label><label>流量显示<select v-model="settingsForm.traffic_unit"><option>GB</option><option>GiB</option><option value="auto">自动</option></select></label><label>独立域名（可选）<input v-model="settingsForm.domain" placeholder="portal.example.com"></label><label>公网入口<input v-model="settingsForm.public_origin" placeholder="http://IP:18088"></label><label class="check">域名开启 HTTPS<input type="checkbox" v-model="settingsForm.https"></label></div><p class="muted">未绑定域名时使用 IP＋端口。同机已有星枢且此域名证书就绪时，会自动关联到本购买面板的反代；其他宝塔 / Nginx 生成本站反代片段供现有平台应用。证书就绪不代表反代已生效，任务页会校验真实入口。</p></section><section class="panel"><h3>域名同步检查</h3><p class="muted">首次绑定或修复已有反代后，可重试配置；无需改动设置或重新连接 VPS。</p><button type="button" :disabled="busy" @click="run(async()=>{const d=await request('admin/gateway/retry','POST',{});notice=d.message})">重试域名配置 / 检查入口</button></section><section class="panel"><h3>注册管控</h3><div class="fields"><label>注册模式<select v-model="settingsForm.registration_mode"><option value="closed">关闭注册</option><option value="invite">邀请码＋邮箱验证</option><option value="allowlist">白名单＋邮箱验证</option><option value="email">直接邮箱验证注册</option></select></label><label>总注册上限<input type="number" v-model.number="settingsForm.registration_limit" min="1" max="500"></label><label class="check">验证后需要管理员审核<input type="checkbox" v-model="settingsForm.approval_required"></label><label class="check">未登录可查看套餐<input type="checkbox" v-model="settingsForm.show_catalog"></label><label class="wide">邮箱白名单<textarea v-model="allowlist" rows="3" placeholder="一行一个邮箱或 @example.com；邀请模式下也可叠加限制"></textarea></label></div></section><section class="panel"><h3>星枢 API 连接 <span class="badge">{{config.secrets.control_configured?'已保存密钥':'待配置'}}</span></h3><div class="fields"><label>星枢 HTTPS 地址<input v-model="secretForm.control_origin" placeholder="https://vps.example.com"></label><label>受限 API 密钥<input type="password" v-model="secretForm.control_key" autocomplete="new-password" placeholder="留空保留原值"></label></div><p class="muted">需要 commerce:read、commerce:write、users:read、subscriptions:read、subscriptions:links、profiles:read、devices:read。请使用单独的购买面板 API 密钥。</p></section><section class="panel"><h3>验证邮件 SMTP</h3><div class="fields"><label>SMTP 主机<input v-model="secretForm.smtp_host"></label><label>安全端口<select v-model.number="secretForm.smtp_port"><option :value="465">465 · TLS</option><option :value="587">587 · STARTTLS</option></select></label><label>登录用户名<input v-model="secretForm.smtp_user"></label><label>邮箱密码 / 授权码<input v-model="secretForm.smtp_password" type="password" placeholder="留空保留原值" autocomplete="new-password"></label><label>发件邮箱<input type="email" v-model="secretForm.smtp_from"></label></div></section><section class="panel"><h3>支付宝在线支付（可选）</h3><p class="muted">使用个人支付宝或微信收款码，请在左侧「收款方式」上传图片；不需要启用本在线通道。</p><div class="fields"><label>应用 APP ID<input v-model="paymentForm.app_id"></label><label>商户 Seller ID<input v-model="paymentForm.seller_id"></label><label>商户应用私钥 PEM<textarea v-model="paymentForm.private_key" rows="4" placeholder="留空保留原值" spellcheck="false"></textarea></label><label>支付宝公钥 PEM<textarea v-model="paymentForm.public_key" rows="4" placeholder="留空保留原值" spellcheck="false"></textarea></label><label class="check">启用支付<input type="checkbox" v-model="paymentForm.enabled"></label><label class="check">沙箱环境<input type="checkbox" v-model="paymentForm.sandbox"></label><label class="check">移动网页支付<input type="checkbox" v-model="paymentForm.mobile"></label></div><p class="muted">启用前需配置可达的 HTTPS 回调入口和已获准的支付宝应用。付款结果以签名回调与主动查询为准。当前回调：{{settingsForm.public_origin}}/portal/v1/payments/alipay/notify</p></section><button class="primary" :disabled="busy">保存设置</button></form></template>

<template v-if="admin&&page==='version'"><section class="panel"><span class="eyebrow">SYSTEM UPDATE</span><h2>保持服务，持续向前。</h2><div class="metrics"><article><span>当前版本</span><strong>v{{version.current}}</strong></article><article><span>最新正式版</span><strong>{{version.latest?'v'+version.latest:'尚未读取'}}</strong></article><article><span>本机更新助手</span><strong class="date">{{version.helper_ready?'在线':'离线 / 未安装'}}</strong></article></div><p class="muted">{{version.message||'更新前备份数据库，验证正式分发包校验值，启动失败自动恢复。更新本购买面板；同机星枢会请求本版所需的官方兼容更新。'}}</p><div class="actions"><button @click="run(load)">检查版本</button><button class="primary" @click="update" :disabled="busy||!version.available||!version.helper_ready">更新到 v{{version.latest||'—'}}</button><a v-if="version.release_url" :href="version.release_url" target="_blank" rel="noreferrer">查看发行说明 ↗</a></div></section><section class="panel"><h3>资源与接入容量</h3><p v-if="capacity.error" class="muted">{{capacity.error}}</p><div class="metrics"><article><span>代理身份使用 / 实现上限</span><strong>{{capacity.identities??'—'}} / {{capacity.identity_limit??'—'}}</strong><small>每个订单一个身份；不是并发人数保证</small></article><article><span>购买用户 / 独立服务</span><strong>{{capacity.registered_customers??'—'}} / {{capacity.portal_services??'—'}}</strong></article></div><div class="resource-grid"><p>应用 <strong>{{version.helper_status?.app_resources||'等待采样'}}</strong></p><p>数据库 <strong>{{version.helper_status?.db_resources||'等待采样'}}</strong></p><p>安装盘可用 / 总容量 <strong>{{version.helper_status?.disk_available||'等待采样'}}</strong></p><p>星枢兼容状态 <strong>{{version.helper_status?.control_compatibility||'等待检查'}}</strong></p></div><p class="muted">应用容器上限 256 MiB，数据库 512 MiB，资源每分钟采样。用户数量与并发承载需结合节点、数据库延迟及实际负载评估，不自动放开内核身份上限。</p></section><section class="panel"><h3>更新与域名任务</h3><div class="list-row" v-for="j in version.jobs" :key="j.id"><div><strong>{{j.kind==='update'?'版本更新':'域名配置'}} · {{j.subject}}</strong><small>{{j.detail||date(j.created_at)}}</small></div><span class="badge">{{states[j.state]}}</span></div></section></template>

<template v-if="admin&&['jobs','audit'].includes(page)"><div class="panel table-wrap"><table><thead><tr><th>任务 / 动作</th><th>对象</th><th>状态 / 操作人</th><th>结果 / 时间</th><th></th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{r.kind||r.action}}</td><td class="mono">{{r.subject}}</td><td>{{states[r.state]||r.actor}}</td><td>{{r.detail||date(r.updated_at||r.created_at)}}</td><td><button v-if="r.state==='failed'&&['fulfill','mail','access'].includes(r.kind)" @click="run(async()=>{await request('admin/jobs','POST',{id:r.id});await load()})">重试</button></td></tr></tbody></table><div v-if="!rows.length" class="empty">暂无记录</div></div></template>
<footer>STARHUB PORTAL <span>✦</span> {{branding.title}} · v{{branding.version||'加载中'}}</footer></main></div>

<OrderPayment v-if="payOrder" :order="payOrder" :request="request" @close="payOrder=null" @changed="load"/>
<div v-if="editor||selectedPlan||thread" class="modal-backdrop" @click.self="editor='';selectedPlan=null;thread=null"><section class="modal" role="dialog" aria-modal="true" :aria-label="selectedPlan?'确认套餐':thread?'工单':'编辑内容'"><div class="section-head"><h2>{{selectedPlan?'确认套餐':thread?'工单 · '+thread.subject:editor==='ticket'?'创建工单':(form.id?'编辑':'新建')+title}}</h2><button @click="editor='';selectedPlan=null;thread=null" aria-label="关闭">×</button></div><div v-if="error" class="alert error">{{error}}</div>
<template v-if="selectedPlan"><h3>{{selectedPlan.name}}</h3><label>购买周期<select v-model="buy.price_id"><option v-for="p in selectedPlan.prices" :value="p.id" :key="p.id">{{p.months}} 个月 · {{money(p.amount)}}</option></select></label><label>优惠码（可选）<input v-model="buy.coupon" maxlength="32"></label><button @click="priceQuote" :disabled="busy">核算价格</button><div v-if="quote" class="quote"><div>原价 <strong>{{money(quote.base_amount)}}</strong></div><div>优惠 <strong>−{{money(quote.discount_amount)}}</strong></div><div>实付 <strong>{{money(quote.payable)}}</strong></div><small>付款期限：{{date(quote.expires_at)}}。创建订单时会重新校验活动名额。</small><button class="primary full" @click="placeOrder" :disabled="busy">创建订单</button></div></template>
<template v-else-if="thread||editor==='ticket'"><div v-for="m in thread?.messages||[]" :key="m.id" class="message"><small>{{m.name}} · {{m.role==='admin'?'管理员':'用户'}} · {{date(m.created_at)}}</small><p class="pre">{{m.body}}</p></div><form @submit.prevent="sendTicket()"><label v-if="!thread">标题<input v-model="ticketForm.subject" required maxlength="120"></label><label>内容<textarea v-model="ticketForm.body" required maxlength="6000" rows="5"/></label><div class="actions"><button class="primary" :disabled="busy">发送</button><button v-if="thread?.state==='open'" type="button" @click="sendTicket(true)" :disabled="busy">关闭工单</button></div></form></template>

<form v-else @submit.prevent="saveEditor"><Fields :fields="planFields" :model="form"/><template v-if="editor==='plans'"><section class="feature-editor"><div class="section-head"><h3>套餐展示信息</h3><button type="button" :disabled="form.display_features.length>=12" @click="form.display_features.push({label:'',value:''})">＋ 添加信息</button></div><p class="muted">例如“峰值速率 / 500 Mbps”“适用场景 / 日常浏览与影音”。最多 12 条，仅用于介绍，不改变真实限速或计费。</p><div class="feature-edit-row" v-for="(f,i) in form.display_features" :key="i"><label>名称<input v-model="f.label" maxlength="24" required placeholder="峰值速率"></label><label>内容<input v-model="f.value" maxlength="160" required placeholder="500 Mbps"></label><button type="button" @click="form.display_features.splice(i,1)" :aria-label="'删除展示信息 '+(Number(i)+1)">移除</button></div></section><p v-if="form.simulation" class="alert">模拟套餐仅展示，不接受真实下单；关闭模拟前请确认用户组、协议、价格及配额。</p><h3>授权星枢用户组</h3><p class="muted">共享密钥节点不能用于购买套餐。请先在星枢建立可计费专用组。</p><label v-for="g in groups" :key="g.id" class="multi"><input type="checkbox" :value="g.id" v-model="form.group_ids">{{g.name}}<small>{{g.services.map((s:Row)=>s.name+(s.managed_users?'':'（共享，不可售）')).join('、')}}</small></label><p v-if="!groups.length" class="alert">请先配置可用的星枢 API 连接，并更新控制面商业接口。</p><h3>允许的协议</h3><div class="actions"><label v-for="p in protocols" :key="p" class="multi"><input type="checkbox" v-model="form.protocols" :value="p">{{p.toUpperCase()}}</label></div><h3>购买周期与价格</h3><div v-for="(p,i) in form.prices" :key="i" class="price-row"><label>周期 ID<input v-model="p.id" pattern="[A-Z0-9_-]{4,32}" required></label><label>月数<input type="number" v-model.number="p.months" min="1" max="12" required></label><label>价格（分）<input type="number" v-model.number="p.amount" min="1" required></label><label>启用<input type="checkbox" v-model="p.enabled"></label><button type="button" @click="form.prices.splice(i,1)" :disabled="form.prices.length===1">移除</button></div><button type="button" @click="form.prices.push({id:'YEAR',months:12,amount:10000,enabled:true})">＋ 添加周期</button></template><div class="modal-actions"><button type="button" @click="editor=''">取消</button><button class="primary" :disabled="busy">{{busy?'保存中…':'保存'}}</button></div></form></section></div>
</template>
